<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\Role\Application\Policy\Filter;

use Throwable;
use Civi\Lughauth\Features\Access\Role\Application\Service\Visibility\RoleRestrictFilterToVisibility;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class RoleAccesible
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __invoke(RoleRestrictFilterToVisibility $event): RoleRestrictFilterToVisibility
    {
        $this->logDebug("Check RoleAccesible Role");
        $span = $this->startSpan("Check RoleAccesible Role");
        try {
            // Roles are scoped to RelyingParties, not directly by tenant.
            // Tenant-level restriction is enforced at the RelyingParty layer.
            return $event;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
